+  await more.click();
+  await page
+    .getByRole("combobox", { name: "Reporting period" })
+    .selectOption("historical");
+  try {
+    await expect(more).toBeDisabled();
+    await expect(page.getByRole("listitem")).toHaveCount(20);
+  } finally {
